const status={draft:'Чернетка',posted:'Проведено',reversed:'Скасовано'};
const groups={purchases:['purchase_order','receipt','supplier_return'],stock:['opening','transfer','writeoff','inventory','production'],sales:['sale','customer_return','customer_order'],finance:['payment','expense','cash_opening','debt_opening','cash_transfer','cash_difference'],staff:['payroll','payroll_payment']};
const roleNames={owner:'Власник',manager:'Керівник магазину',cashier:'Касир',warehouse:'Склад',accountant:'Бухгалтер'};
const roles={owner:[...tabs],manager:['purchases','stock','sales','finance','customers','reports'],cashier:['sales','stock','customers'],warehouse:['purchases','stock'],accountant:['finance','staff','customers','reports']};
const lineKinds=new Set(['purchase_order','receipt','opening','sale','customer_return','supplier_return','transfer','writeoff','inventory','production','customer_order']);
const priceKinds=new Set(['purchase_order','receipt','opening','sale','customer_order','inventory']);
const roleKinds={owner:Object.keys(kinds),manager:Object.keys(kinds).filter(k=>!['payroll','payroll_payment','cash_opening','debt_opening'].includes(k)),cashier:['sale','customer_return','customer_order'],warehouse:['purchase_order','receipt','opening','supplier_return','transfer','writeoff','inventory','production'],accountant:['payment','expense','cash_opening','payroll','payroll_payment','debt_opening','cash_transfer','cash_difference']};
let current=null,generation=0,E=null,P=[],C={},csrf='',listPage=1,filterStatus='',filterStore='',search='',stockData=null,assortmentWarehouse='',assortmentData=null,assortmentNotice=null,assortmentOpen=false;
const main=()=>document.getElementById('main');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
