const unitPrice=n=>new Intl.NumberFormat('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(n||0));
const quantity=n=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:3}).format(Number(n||0));
const date=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const calendarDay=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const dayOffset=(value,days)=>{const d=new Date(`${value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);};
const openShifts=store=>(E.active_shifts||E.shifts).filter(s=>s.store_id===Number(store)&&!s.closed_at&&(E.role!=='cashier'||s.opened_by===E.username));
const name=(list,id)=>E?.[list]?.find(x=>String(x.id)===String(id))?.name||'—';
const option=(values,selected='',empty='Виберіть…')=>`<option value="">${esc(empty)}</option>`+values.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)}</option>`).join('');
const field=(label,input,cls='')=>`<label class="${cls}">${label}${input}</label>`;
