const pendingActions=new WeakSet();
document.addEventListener('click',e=>{const el=e.target.closest('[data-trade]');if(!el)return;e.preventDefault();if(el.disabled||pendingActions.has(el)||el.closest('dialog')?.dataset.busy==='1')return;const wasAriaDisabled=el.getAttribute('aria-disabled'),d=el.closest('dialog');pendingActions.add(el);el.setAttribute('aria-disabled','true');Promise.resolve(act(el.dataset.trade,el)).catch(error=>formError(error,d||dialog)).finally(()=>{pendingActions.delete(el);if(el.isConnected){if(wasAriaDisabled===null)el.removeAttribute('aria-disabled');else el.setAttribute('aria-disabled',wasAriaDisabled);}});});
document.addEventListener('toggle',e=>{if(e.target.dataset?.disclosure!=='stock-assortment'||!main().contains(e.target))return;assortmentOpen=e.target.open;if(assortmentOpen&&!assortmentData&&assortmentWarehouse)draw().catch(errorPanel);},true);
document.addEventListener('change',e=>{if(!main().contains(e.target))return;captureAssortmentDraft(e.target);if(e.target.name==='filterStore'){filterStore=e.target.value;listPage=1;draw().catch(errorPanel);}if(e.target.name==='assortmentWarehouse'){assortmentWarehouse=e.target.value;assortmentNotice=null;e.target.closest('[data-assortment-warehouse]').querySelectorAll('tbody input,tbody button').forEach(control=>control.disabled=true);draw().catch(errorPanel);}if(e.target.name==='filterStatus'){filterStatus=e.target.value;listPage=1;draw().catch(errorPanel);}});
// Only the draw that actually replaces the list restores the search field, with the text and caret as they are at that moment.
function searchFocus(){const a=document.activeElement;if(!a||!main().contains(a))return null;let selector;
 if(['stockSearch','partySearch'].includes(a.name))selector=`[name=${a.name}]`;
 else if(a.dataset.assortmentSold)selector=`[data-assortment-sold="${CSS.escape(a.dataset.assortmentSold)}"]`;
 else if(a.dataset.assortmentMin)selector=`[data-assortment-min="${CSS.escape(a.dataset.assortmentMin)}"]`;
 else if(['assortment-save','assortment-reset'].includes(a.dataset.trade))selector=`[data-trade="${a.dataset.trade}"][data-product="${CSS.escape(a.dataset.product)}"]`;
 else return null;
 const {value,selectionStart:start,selectionEnd:end,selectionDirection:direction}=a;return ()=>{const x=main().querySelector(selector);if(!x)return;if(['stockSearch','partySearch'].includes(a.name))x.value=value;x.focus({preventScroll:true});try{x.setSelectionRange(start,end,direction||'none');}catch(_){}};
}
let searchTimer;document.addEventListener('input',e=>{if(main().contains(e.target))captureAssortmentDraft(e.target);if(!['stockSearch','partySearch'].includes(e.target.name))return;search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>draw().catch(errorPanel),250);});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-trade=report-mode]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const mode=e.key==='Home'?'period':e.key==='End'?'balances':tab.dataset.mode==='period'?'balances':'period';tab.parentElement.querySelector(`[data-mode="${mode}"]`)?.click();});
document.addEventListener('submit',async e=>{if(e.target.id!=='tradeReportForm')return;e.preventDefault();const form=e.target;if(form.dataset.busy==='1')return;const values=Object.fromEntries(new FormData(form)),token=generation,tab=current,result=document.getElementById('tradeReportResult'),status=document.getElementById('tradeReportStatus'),error=document.getElementById('tradeReportError'),disabled=[...form.querySelectorAll('button,input,select')].map(x=>[x,x.disabled]);form.dataset.busy='1';form.setAttribute('aria-busy','true');result.setAttribute('aria-busy','true');disabled.forEach(([x])=>x.disabled=true);status.textContent='Оновлення звіту…';error.textContent='';try{const r=await api('report?'+new URLSearchParams(values));if(token!==generation||tab!==current||!form.isConnected)return;filterStore=values.store;reportState={...(reportState||{}),...values};result.innerHTML=r.mode==='balances'?balanceReportContent(r):reportContent(r);financeControls.forEach(control=>control.setStore(values.store));}catch(e){if(form.isConnected&&token===generation&&tab===current){error.textContent=e.message;error.focus({preventScroll:true});error.scrollIntoView({block:'nearest'});}}finally{delete form.dataset.busy;form.removeAttribute('aria-busy');result.removeAttribute('aria-busy');disabled.forEach(([x,wasDisabled])=>{if(x.isConnected)x.disabled=wasDisabled;});status.textContent='';}});
window.addEventListener('beforeunload',e=>{if(assortmentDrafts.size||assortmentPending.size||dialog?.open&&(dialog.dataset.dirty==='1'||dialog.dataset.busy==='1')){e.preventDefault();e.returnValue='';}});
