window.Trade={canLeave,handles:tab=>tabs.has(tab),mount(tab){if(current===tab)return;window.TradeBrowse.close();financeUI.closeAudit();cancelFinanceControls();cancelShiftControls();if(dialog?.open)dialog.close();current=tab;const token=++generation;listPage=1;search='';main().innerHTML='<section class="panel"><p role="status">Завантаження обліку…</p></section>';load().then(()=>{if(token===generation&&current===tab)draw().catch(errorPanel);}).catch(error=>{if(token===generation&&current===tab)errorPanel(error);});},leave(){window.TradeBrowse.close();financeUI.closeAudit();cancelFinanceControls();cancelShiftControls();if(current){current=null;generation++;}if(dialog?.open)dialog.close();}};
